// src/pages/Incidents.jsx
//
// Incidents page — shows persistent incident logs and bottlenecks triggered by
// high vehicle density frames, simulation scenarios, or road obstruction events.
//
// Features:
//   • Real-time updates via Socket.io
//   • Persistent history fetched from backend (/api/incidents)
//   • Filter tabs: All, Active, Resolved
//   • Status toggle / Resolve action button for active incidents
//   • Severity and risk score indicators
//
// ⚠️ DEMO NOTE: Incidents are stored persistently in backend/data/incidents.json
// and generated by YOLO detection thresholds or demo scenarios.

import { useState, useEffect } from 'react'
import { fetchIncidents, resolveIncident } from '../services/api.js'
import socket from '../services/socket.js'
import { useAuth } from '../context/AuthContext.jsx'

const SEVERITY_BADGE = {
  Low:      'badge badge--free',
  Medium:   'badge badge--moderate',
  High:     'badge badge--heavy',
  Critical: 'badge badge--critical',
}

export default function Incidents() {
  const { isAdmin } = useAuth()
  const [incidents, setIncidents] = useState([])
  const [analytics, setAnalytics] = useState(null)
  const [filterStatus, setFilterStatus] = useState('All') // 'All' | 'Active' | 'Resolved'
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  const [resolvingId, setResolvingId] = useState(null)

  const loadIncidents = async () => {
    try {
      setLoading(true)
      const data = await fetchIncidents()
      setIncidents(data.incidents || [])
      setAnalytics(data.analytics || null)
      setError(null)
    } catch (err) {
      setError(err.message)
      setIncidents([])
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadIncidents()

    // Connect to WebSocket for instant real-time incident updates
    socket.connect()
    const onLiveUpdate = (payload) => {
      if (payload && payload.incidents) {
        setIncidents(payload.incidents)
        if (payload.incident_analytics) {
          setAnalytics(payload.incident_analytics)
        }
        setError(null)
        setLoading(false)
      }
    }

    socket.on('live_traffic_update', onLiveUpdate)

    return () => {
      socket.off('live_traffic_update', onLiveUpdate)
    }
  }, [])

  const handleResolve = async (id) => {
    try {
      setResolvingId(id)
      // Emit via socket for instant broadcast, and call API
      socket.emit('resolve_incident', id)
      await resolveIncident(id)
      // Optimistically update local state
      setIncidents(prev =>
        prev.map(inc => inc.id === id ? { ...inc, status: 'Resolved' } : inc)
      )
    } catch (err) {
      console.error('Failed to resolve incident:', err)
    } finally {
      setResolvingId(null)
    }
  }

  // Filtered incidents based on active tab
  const filteredIncidents = incidents.filter(inc => {
    if (filterStatus === 'Active') return (inc.status || 'Active') === 'Active'
    if (filterStatus === 'Resolved') return inc.status === 'Resolved'
    return true
  })

  const activeCount = incidents.filter(i => (i.status || 'Active') === 'Active').length
  const resolvedCount = incidents.filter(i => i.status === 'Resolved').length

  const formatTimestamp = (ts) => {
    if (!ts) return 'N/A'
    try {
      const d = new Date(ts)
      if (isNaN(d.getTime())) return String(ts)
      return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
    } catch {
      return String(ts)
    }
  }

  return (
    <div className="page-container">
      <div className="page-header">
        <div>
          <h1 className="page-title">⚠️ Incidents &amp; Bottlenecks</h1>
          <p className="page-subtitle">
            Persistent incident logs with lifecycle status and real-time alerts
          </p>
        </div>
        <button className="btn-refresh" onClick={loadIncidents}>↻ Refresh</button>
      </div>

      {/* Summary KPI Cards */}
      <div className="summary-grid" style={{ marginBottom: '1.5rem' }}>
        <div className="card stat-card">
          <div className="stat-card__label">Total Recorded</div>
          <div className="stat-card__value">{incidents.length}</div>
          <div className="stat-card__note">Persistent JSON database</div>
        </div>

        <div className="card stat-card">
          <div className="stat-card__label">Active Bottlenecks</div>
          <div className="stat-card__value" style={{ color: activeCount > 0 ? 'var(--red, #ef4444)' : 'var(--green, #22c55e)' }}>
            {activeCount}
          </div>
          <div className="stat-card__note">Requires immediate clearance</div>
        </div>

        <div className="card stat-card">
          <div className="stat-card__label">Resolved Incidents</div>
          <div className="stat-card__value" style={{ color: 'var(--green, #22c55e)' }}>
            {resolvedCount}
          </div>
          <div className="stat-card__note">Traffic normalisation confirmed</div>
        </div>

        <div className="card stat-card">
          <div className="stat-card__label">Avg Risk Score (Rt)</div>
          <div className="stat-card__value" style={{ color: 'var(--amber, #f59e0b)' }}>
            {analytics?.average_risk_score ?? (incidents.length > 0 ? Math.round(incidents.reduce((s, i) => s + (i.risk_score || i.score || 0), 0) / incidents.length) : 0)}
          </div>
          <div className="stat-card__note">Rule-based score scale 0–100</div>
        </div>
      </div>

      {/* Filter Tabs */}
      <div className="incident-tabs" style={{ display: 'flex', gap: '0.5rem', marginBottom: '1rem', alignItems: 'center' }}>
        <span style={{ fontSize: '0.85rem', color: 'var(--text-muted)', marginRight: '0.5rem' }}>Filter by Status:</span>
        <button
          className={`incident-tab-btn ${filterStatus === 'All' ? 'incident-tab-btn--active' : ''}`}
          onClick={() => setFilterStatus('All')}
        >
          All ({incidents.length})
        </button>
        <button
          className={`incident-tab-btn ${filterStatus === 'Active' ? 'incident-tab-btn--active' : ''}`}
          onClick={() => setFilterStatus('Active')}
        >
          Active ({activeCount})
        </button>
        <button
          className={`incident-tab-btn ${filterStatus === 'Resolved' ? 'incident-tab-btn--active' : ''}`}
          onClick={() => setFilterStatus('Resolved')}
        >
          Resolved ({resolvedCount})
        </button>
      </div>

      {/* Data provenance notice */}
      <div className="demo-banner" role="note">
        <span aria-hidden="true">ℹ️</span>
        <span>
          <strong>Storage Layer:</strong> Incidents are persistently stored in backend local storage
          (<code>backend/data/incidents.json</code>). Status updates persist across page reloads.
        </span>
      </div>

      {/* Error state */}
      {error && (
        <div className="demo-banner" role="alert" aria-live="polite">
          <span aria-hidden="true">⚠️</span>
          <span>Backend unavailable — incident data cannot be loaded. ({error})</span>
        </div>
      )}

      {/* Loading */}
      {loading && !error && (
        <div className="page-empty-state">
          <span className="page-empty-state__icon">⏳</span>
          <p>Loading incident records…</p>
        </div>
      )}

      {/* Empty state */}
      {!loading && !error && filteredIncidents.length === 0 && (
        <div className="page-empty-state">
          <span className="page-empty-state__icon">✅</span>
          <h2>No {filterStatus !== 'All' ? filterStatus : ''} Incidents Found</h2>
          <p>
            {filterStatus === 'Active'
              ? 'All traffic incidents are currently resolved and operating normally.'
              : 'No incident records match the current filter.'}
          </p>
        </div>
      )}

      {/* Persistent Incident table */}
      {!loading && filteredIncidents.length > 0 && (
        <div className="card">
          <div className="card__header">
            <span className="card__title">Incident History Log</span>
            <span className="card__subtitle">{filteredIncidents.length} shown</span>
          </div>
          <div className="card__body--flush">
            <table className="det-table">
              <thead>
                <tr>
                  <th>ID</th>
                  <th>Time</th>
                  <th>Location Node</th>
                  <th>Vehicles</th>
                  <th>Severity</th>
                  <th>Score (Rt)</th>
                  <th>Status</th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {filteredIncidents.map(inc => {
                  const isActive = (inc.status || 'Active') === 'Active'
                  const score = inc.risk_score !== undefined ? inc.risk_score : (inc.score || 0)
                  return (
                    <tr key={inc.id}>
                      <td className="det-id" style={{ whiteSpace: 'nowrap' }}>{inc.id}</td>
                      <td className="det-time">{formatTimestamp(inc.timestamp || inc.timestamp_sec)}</td>
                      <td className="det-class">
                        <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', flexWrap: 'wrap' }}>
                          <strong>{inc.node_location || inc.zone_name}</strong>
                          {inc.sub_zone && (
                            <span style={{ fontSize: '0.7rem', background: 'rgba(56, 189, 248, 0.15)', color: 'var(--blue)', padding: '0.1rem 0.4rem', borderRadius: '4px', fontWeight: 600 }}>
                              📍 {inc.sub_zone}
                            </span>
                          )}
                        </div>
                        {inc.description && (
                          <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: '2px' }}>
                            {inc.description}
                          </div>
                        )}
                      </td>
                      <td style={{ fontWeight: 700, color: 'var(--amber)' }}>
                        {inc.vehicle_count || '—'}
                      </td>
                      <td>
                        <span className={SEVERITY_BADGE[inc.severity] || 'badge'}>
                          {inc.severity}
                        </span>
                      </td>
                      <td style={{ fontFamily: 'var(--mono)', fontWeight: 600 }}>
                        {score}
                      </td>
                      <td>
                        <span className={`badge ${isActive ? 'badge--critical' : 'badge--free'}`} style={{ textTransform: 'uppercase', fontSize: '0.72rem' }}>
                          {isActive ? '● Active' : '✓ Resolved'}
                        </span>
                      </td>
                      <td>
                        {isActive ? (
                          <button
                            className="btn-resolve"
                            disabled={!isAdmin || resolvingId === inc.id}
                            onClick={() => handleResolve(inc.id)}
                            title={!isAdmin ? '🔒 Admin role required to resolve incidents' : 'Mark incident as resolved'}
                            style={!isAdmin ? { opacity: 0.5, cursor: 'not-allowed' } : {}}
                          >
                            {resolvingId === inc.id ? 'Resolving…' : !isAdmin ? '🔒 Admin' : 'Resolve'}
                          </button>
                        ) : (
                          <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Closed</span>
                        )}
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  )
}
